class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]   # path compression
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self.parent[ra] = rb
        return ra != rb          # False if they were already joined

uf = UnionFind(6)
uf.union(0, 1); uf.union(1, 2); uf.union(4, 5)
print(uf.find(0) == uf.find(2), uf.find(0) == uf.find(4))   # True False
print(uf.union(0, 2))                                       # False: already connected

a = {"python", "sql", "linux"}
b = {"sql", "docker", "linux", "nginx"}
print(sorted(a | b))          # union
print(sorted(a & b))          # intersection: ['linux', 'sql']
print(sorted(a - b))          # difference: ['python']
print("sql" in a)             # True, an O(1) average membership test

text = "the cat and the hat and the bat"
counts = {}
for word in text.split():
    counts[word] = counts.get(word, 0) + 1
print(counts)                       # {'the': 3, 'cat': 1, 'and': 2, 'hat': 1, 'bat': 1}

groups = {}
for word in counts:
    groups.setdefault(len(word), []).append(word)
print(groups)                       # {3: ['the', 'cat', 'and', 'hat', 'bat']}

def greedy_color(graph):
    colors = {}
    for node in sorted(graph):
        taken = {colors[n] for n in graph[node] if n in colors}
        colors[node] = next(c for c in range(len(graph)) if c not in taken)
    return colors

